const secret = $env.KURO_WEBHOOK_SECRET || '';
const got = $json.headers?.['x-kuro-secret'] || $json.headers?.['X-Kuro-Secret'] || '';
if (!secret || got !== secret) {
  return [{ json: { ok: false, error: 'unauthorized', status: 401 } }];
}
const mode = ($json.body?.mode || $json.query?.mode || 'summary').toString();
return [{ json: { ok: true, mode } }];
